{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attachment to user",
      "resource": "aws_iam_user_policy_attachment.privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy",
      "severity": "HIGH",
      "explanation": "Attaching policies directly to IAM users is a security risk as it makes it harder to manage permissions and increases the risk of privilege escalation. It is recommended to attach policies to groups or roles instead."
    }
  ],
  "patched_code": "resource \"aws_iam_group\" \"privesc18-PassExistingRoleToNewGlueDevEndpoint-group\" {\n  name = \"privesc18-PassExistingRoleToNewGlueDevEndpoint-group\"\n}\n\nresource \"aws_iam_user_group_membership\" \"privesc18-PassExistingRoleToNewGlueDevEndpoint-user-group-membership\" {\n  user = aws_iam_user.privesc18-PassExistingRoleToNewGlueDevEndpoint-user.name\n  groups = [aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name]\n}\n\nresource \"aws_iam_group_policy_attachment\" \"privesc18-PassExistingRoleToNewGlueDevEndpoint-group-attach-policy\" {\n  group      = aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name\n  policy_arn = aws_iam_policy.privesc18-PassExistingRoleToNewGlueDevEndpoint.arn\n}",
  "fix_summary": "Replaced the direct attachment of the policy to the IAM user with a group-based approach. Created an IAM group, added the user to the group, and attached the policy to the group instead."
}
